// =====================================================================
//  RÉFÉRENTIEL D'ÉVALUATION — Bonnes Pratiques d'Entreposage (GWP/GSP)
//  Basé sur : outil Excel GWP_Assessment_FR (GHSC-FTA), OMS TRS 1025
//  Annexe 7 (2020) "Good storage and distribution practices for medical
//  products", checklist PFSCM "Pharmaceutical Wholesaler Site Inspection",
//  questionnaire USAID | DELIVER "Warehouse Assessment Tool", USAID
//  "Guidelines for Warehousing Health Commodities", OMS TRS 961 Annexe 9.
//
//  Structure : domaine > section > critère
//  Criticité : C = Critique (poids 3), M = Majeur (poids 2), m = Mineur (1)
//  na : true  => la réponse "Non applicable" est autorisée
//  type "checklist" => score = proportion d'items cochés
//  scope : 'org' = répondu une fois pour la centrale (politique, SOP, système,
//          programme, organisation) et hérité par tous ses entrepôts ;
//          absent (= 'site') = constat propre à chaque entrepôt/bâtiment.
// =====================================================================

export const CRITICALITY = {
  C: { label: 'Critique', weight: 3, short: 'C' },
  M: { label: 'Majeur', weight: 2, short: 'M' },
  m: { label: 'Mineur', weight: 1, short: 'm' },
};

export const ANSWERS = {
  yes: { label: 'Conforme', value: 1, short: 'C' },
  partial: { label: 'Partiel', value: 0.5, short: 'P' },
  no: { label: 'Non conforme', value: 0, short: 'NC' },
  na: { label: 'N/A', value: null, short: 'NA' },
};

