// Utilitaires de parcours
export function allCriteria() {
  const out = [];
  for (const d of DOMAINS) for (const s of d.sections) for (const c of s.criteria) out.push({ ...c, domainId: d.id, sectionId: s.id });
  return out;
}
export function criteriaCount() { return allCriteria().length; }
export const isOrg = c => c.scope === 'org';
export function orgCriteria() { return allCriteria().filter(isOrg); }
export function siteCriteria() { return allCriteria().filter(c => !isOrg(c)); }
